DELETE FROM t_mp_final_structure_allocation_log
 WHERE FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{year,jdbcType=DECIMAL}
   AND MONTH = #{month,jdbcType=DECIMAL}
   AND MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
   AND PRODUCTION_VERSION = #{productionVersion,jdbcType=VARCHAR};
DELETE FROM t_mp_final_statistics_log
 WHERE FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{year,jdbcType=DECIMAL}
   AND MONTH = #{month,jdbcType=DECIMAL}
   AND MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
   AND PRODUCTION_VERSION = #{productionVersion,jdbcType=VARCHAR};
